-- Reused from our own MapHub v0.8.0; third-party records remain MIT licensed.
-- See DATA-LICENSES.txt for credits and limitations.
-- Additional researched and licensed location data. Loaded automatically at startup.
-- See DATA-SOURCES.txt for licensing and status; coordinates denote known places, not live spawns.
local out = GHN.CuratedLocations or {}
GHN.CuratedLocations = out
local function add(map, xy, category, name, npc, quest, source)
 if not map or not xy or #xy ~= 8 then return end
 local x,y = tonumber(xy:sub(1,4)),tonumber(xy:sub(5,8))
 if not x or not y or x > 10000 or y > 10000 then return end
 local id = ('expanded:%d:%s:%s:%s'):format(map,category,xy,tostring(npc or ''))
 out[#out+1] = {
   id=id, mapID=map, x=x/100, y=y/100, name=name or 'Discovery',
   category=category, npcID=tonumber(npc), questID=tonumber(quest),
   source=source or 'Licensed public map records',
   description='Documented location; this icon does not mean the rare or treasure is currently spawned.'
 }
end

